        address baseToken = address(0);
        address nft = address(0x123);
        bytes32 merkleRoot = bytes32(0);
        bool useStolen = false;
        bool payRoyalties = false;

        bool ok;
        try c.initialize(baseToken, nft, vBase, vNft, changeFee, fuzzFeeRate, merkleRoot, useStolen, payRoyalties) {
